starter.en:
app.post('/api/reports', async (req, res) => {
  const { userId, query } = req.body;
  const sql = `SELECT * FROM events WHERE user_id = ${userId} AND note LIKE '%${query}%'`;
  const rows = await db.raw(sql);
  const summary = await llm.complete(`Summarize these events for the user: ${JSON.stringify(rows)}`);
  res.json({ summary });
});

